"use client";
import * as React from "react";
import { cva } from "class-variance-authority";
import { cn } from "@/lib/utils";
export const textareaVariants = cva(
  "v-textarea block w-full min-h-[128px] resize-y rounded-[20px] [border:0] bg-[var(--input)] px-[18px] py-[16px] text-[15px] leading-[1.5] text-[color:var(--v-text)] [box-shadow:inset_0_0_0_1px_var(--v-edge)] outline-none placeholder:text-[color:var(--v-text-2)]",
);
export type TextareaProps = React.ComponentProps<"textarea">;
export function Textarea({ className, ...props }: TextareaProps) {
  return (
    <textarea
      data-slot="textarea"
      data-part="root"
      className={cn(textareaVariants(), className)}
      {...props}
    />
  );
}
export type TextareaComposerProps = React.ComponentProps<"div">;
export function TextareaComposer({
  className,
  ...props
}: TextareaComposerProps) {
  return (
    <div
      data-slot="textarea-composer"
      data-part="root"
      className={cn(
        "v-composer grid gap-0 rounded-[22px] bg-[var(--input)] [box-shadow:inset_0_0_0_1px_var(--v-edge)]",
        className,
      )}
      {...props}
    />
  );
}
export type TextareaComposerBarProps = React.ComponentProps<"div">;
export function TextareaComposerBar({
  className,
  ...props
}: TextareaComposerBarProps) {
  return (
    <div
      data-slot="textarea-composer-bar"
      data-part="footer"
      className={cn(
        "v-composer__bar flex items-center gap-[8px] pt-[6px] pr-[8px] pb-[8px] pl-[16px]",
        className,
      )}
      {...props}
    />
  );
}
export type TextareaCountProps = React.ComponentProps<"span"> & {
  value: string;
  maxLength?: number;
};
export function TextareaCount({
  value,
  maxLength,
  className,
  ...props
}: TextareaCountProps) {
  return (
    <span
      data-slot="textarea-count"
      className={cn(
        "v-composer__count text-[12px] text-[color:var(--v-text-2)] tabular-nums",
        className,
      )}
      {...props}
    >
      {value.length}
      {maxLength !== undefined && ` / ${maxLength}`}
    </span>
  );
}

@layer sahajiv-states {
[data-slot="textarea"],
[data-slot="textarea-composer"] {
  transition:
    background var(--t-micro),
    box-shadow var(--t-micro);
}
[data-slot="textarea"]:hover:not(:focus) {
  background: color-mix(in oklab, var(--input) 92%, var(--v-canvas));
}
[data-slot="textarea"]:focus,
[data-slot="textarea-composer"]:focus-within {
  outline: none;
  background: var(--v-pink-soft);
  box-shadow: inset 0 0 0 2px var(--v-brand);
}
[data-slot="textarea"]::-webkit-resizer {
  display: none;
}
:root[data-mode="dark"]
  :is([data-slot="textarea"], [data-slot="textarea-composer"]) {
  background: var(--v-beige);
  box-shadow: inset 0 0 0 1px var(--v-border);
}
:root[data-mode="dark"] [data-slot="textarea"]:focus,
:root[data-mode="dark"] [data-slot="textarea-composer"]:focus-within {
  background: color-mix(in oklab, var(--v-pink) 14%, var(--v-canvas));
  box-shadow: inset 0 0 0 2px var(--v-pink);
}
[data-slot="textarea-composer"] .v-textarea,
[data-slot="textarea-composer"] .v-textarea:is(:focus, :hover) {
  background: transparent;
  box-shadow: none;
  border-radius: 22px 22px 0 0;
  min-height: 96px;
  resize: none;
  padding: 16px 18px 6px;
}
[data-slot="textarea-composer-bar"] .v-meta {
  flex: 1;
  min-width: 0;
}
[data-slot="textarea-composer-bar"] .v-ibtn {
  width: 36px;
  height: 36px;
  box-shadow: inset 0 0 0 1px var(--v-border);
  background: var(--v-canvas);
}
[data-slot="textarea-composer-bar"] .v-ibtn:hover {
  background: var(--v-beige);
}
[data-slot="textarea-composer-bar"] .v-ibtn:is(.-ink, .-pink) {
  box-shadow: none;
}
[data-slot="textarea-composer-bar"] .v-ibtn.-pink {
  background: var(--v-pink);
  color: var(--v-on-accent);
  border-radius: 46% 54% 50% 50%/50% 46% 54% 50%;
  width: 40px;
  height: 40px;
}
[data-slot="textarea-composer-bar"] .v-ibtn.-pink:hover {
  background: var(--v-pink-deep);
}
:root[data-mode="dark"] [data-slot="textarea-composer-bar"] .v-ibtn {
  background: var(--v-beige-2);
  box-shadow: none;
}
[data-slot="textarea"]:disabled {
  background: var(--v-disabled-face);
  color: var(--v-disabled-ink);
  box-shadow: inset 0 0 0 1px var(--v-disabled-edge);
  cursor: not-allowed;
}

}
